def selfDescribingOfLength(d):
    out = []
    prefix = []

    def build(slots, remaining):
        if slots == 0:
            if remaining == 0:
                counts = [prefix.count(i) for i in range(d)]
                if counts == prefix:
                    out.append(int("".join(map(str, prefix))))
            return
        for v in range(remaining + 1):
            prefix.append(v)
            build(slots - 1, remaining - v)
            prefix.pop()

    build(d, d)
    return out
